import json
import sys

def validate_and_sort(line):
    try:
        obj = json.loads(line)
    except (json.JSONDecodeError, ValueError):
        return {"error": "invalid_input"}

    if not isinstance(obj, dict):
        return {"error": "invalid_input"}

    # Must have exactly 'op' and 'items' keys
    if set(obj.keys()) != {"op", "items"}:
        return {"error": "invalid_input"}

    if obj["op"] != "sort":
        return {"error": "invalid_input"}

    items = obj["items"]
    if not isinstance(items, list):
        return {"error": "invalid_input"}

    for item in items:
        if not isinstance(item, dict):
            return {"error": "invalid_input"}
        if set(item.keys()) != {"id", "quantity"}:
            return {"error": "invalid_input"}
        if not isinstance(item["id"], str):
            return {"error": "invalid_input"}
        if not isinstance(item["quantity"], int) or isinstance(item["quantity"], bool):
            return {"error": "invalid_input"}

    # Stable sort descending by quantity
    sorted_items = sorted(items, key=lambda x: x["quantity"], reverse=True)

    return {"items": sorted_items}

for line in sys.stdin:
    line = line.strip()
    if line:
        result = validate_and_sort(line)
        print(json.dumps(result, separators=(",", ":")))
